  "employETitle": "E. Le site",
  "employEWalk": "<a href=\"/\" class=\"text-amber-300 underline\">Accueil</a> · <a href=\"/chat.html\" class=\"text-amber-300 underline\">Chat</a> · <a href=\"/employ.html\" class=\"text-amber-300 underline\">Employer</a> · <a href=\"/Launch-Ra-Thor.html\" class=\"text-amber-300 underline\">Lancer</a> · <a href=\"/micro-moment.html\" class=\"text-amber-300 underline\">Moments</a> · <a href=\"/sovereign-shard.html\" class=\"text-amber-300 underline\">Éclat</a> · <a href=\"/web-forge.html\" class=\"text-amber-300 underline\">Forge</a> · <a href=\"/contact.html\" class=\"text-amber-300 underline\">Contact</a> · <a href=\"/privacy.html\" class=\"text-amber-300 underline\">Confidentialité</a>",
  "employFBody": "AG-SML: personnel / recherche / indépendant modeste. Commercial / organisation / revenus → licence payante. Utilisez le <a href=\"/contact.html#commercial-inquiry\" class=\"text-amber-300 underline\">formulaire de demande commerciale</a> ou écrivez à <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 underline\">info@Rathor.ai</a>.",
  "employFTitle": "F. Licence",
  "employGBody": "No measured METR chiffres. Sans dépôt de certification. Le dossier de travail est un <strong class=\"text-amber-300\">DRAFT</strong>.",
  "employGTitle": "G. Lacunes honnêtes",
  "employLoop1": "<strong class=\"text-amber-300\">Intention</strong> — demandez un brouillon, un plan, une relecture ou un refus.",
  "employLoop2": "<strong class=\"text-amber-300\">Passer les portes</strong> — TOLC 8 est l'épreuve permanente.",
  "employLoop3": "<strong class=\"text-amber-300\">Modèle optionnel</strong> — restez sur l'appareil, ou copiez le contexte dans un modèle que vous choisissez. Une session Grok optionnelle n'est pas un produit xAI.",
  "employLoop4": "<strong class=\"text-amber-300\">Relecture</strong> — lisez le brouillon. Gardez ou refusez.",
  "employLoop5": "<strong class=\"text-amber-300\">Agir</strong> — l'action vous appartient.",
  "employLoopFoot": "Contrat du modèle optionnel : <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/OPTIONAL_MODEL.md\" class=\"text-amber-300 underline\">docs/OPTIONAL_MODEL.md</a>. Pas une intégration certifiée d'AgentOS ni de Hermes.",
  "employLoopTitle": "La boucle",
  "employOrgBuy": "Ce qu'ils achètent : du temps et des droits pour envelopper un flux de travail sous la même constitution. Inspecter la coque d'admission. Garder ou refuser.",
  "employOrgHow": "Comment demander : le formulaire de <a href=\"/contact.html#commercial-inquiry\" class=\"text-amber-300 underline\">demande commerciale</a> ou <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 underline\">info@Rathor.ai</a>. Un humain répond. Il n'y a pas de clé de licence instantanée.",
  "employOrgNot": "Ce qu'ils n'achètent pas : conformité ISO 42001, conformité à l'EU AI Act, chiffres ≠ METR, une garantie AGSi, un proxy de clé hébergé, ni un monde achevé.",
  "employOrgTitle": "Organisations",
  "employOrgWho": "Qui paie : usage à l'échelle de l'organisation, usage qui génère des revenus, un produit intégré, un service aux clients, ou une constitution pour les agents du personnel.",
  "employSisterBody": "Le curriculum, le jeu humain et les études inspectables vivent dans leurs propres dépôts GitHub — pas comme des portes produit en plus sur ce site. Ouvrez la carte : <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/SISTER_ADOPTION.md\" class=\"text-amber-300 underline\">docs/SISTER_ADOPTION.md</a>. Le travail Fusion, High-Tc, protéines et vaisseau-monde reste des études que vous inspectez là.",
  "employSisterTitle": "Arbres publics frères",
  "employSpine": "Colonne : <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/EMPLOY.md\" class=\"text-amber-300 underline\">docs/EMPLOY.md</a>. Exposé public : <a href=\"/briefing.html\" class=\"text-amber-300 underline\">/briefing.html</a>.",
  "employStamp": "16 septembre 2026 · espace de travail 14.15.6 · Capable · Borné · Corrigible",
